<?php require_once __DIR__.'/../config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: '.($u['role']==='admin'?'/powervault/admin/':'/powervault/account/'));exit;}else $error='Incorrect email or password.';}$pageTitle='Login';require __DIR__.'/../includes/header.php';?><section class="section-pad"><div class="container auth-wrap"><form method="post" class="form-panel auth-card"><div class="eyebrow">WELCOME BACK</div><h1>Log in</h1><?=$error?'<div class="alert error">'.e($error).'</div>':''?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Password</label><input class="form-control mb-4" name="password" type="password" required><button class="btn btn-neon w-100">Login</button><p class="muted mt-3">New here? <a href="/powervault/account/register.php">Create an account</a></p></form></div></section><?php require __DIR__.'/../includes/footer.php';?>
